<?php
namespace Srms;
final class Imports {
 public const TEMPLATES=[
 'parcels'=>['account_number','land_id','plot_size','plot_size_unit','land_description','locality','digital_address'],
 'ratepayers'=>['ratepayer_number','full_name','ratepayer_type','organization_name','email','postal_address'],
 
 'opening_balances'=>['account_number','billing_year','amount','due_date','reference'],
 ];
 public static function template(string $type): never {Auth::staff();$headers=self::TEMPLATES[$type]??throw new \DomainException('Invalid import type.');header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="'.$type.'-template.csv"');$out=fopen('php://output','w');fputcsv($out,$headers);fclose($out);exit;}
 public static function normalize(string $type,array $row): array {
  foreach($row as $k=>$v)$row[$k]=trim((string)$v);
  if($type==='parcels'){$row['account_number']=AccountNumber::validate(require_value($row,'account_number'));if(!empty($row['plot_size']))Money::parse($row['plot_size']);if(Database::one('SELECT id FROM properties WHERE property_number=? OR (land_id IS NOT NULL AND land_id=?)',[$row['account_number'],$row['land_id']??'']))throw new \DomainException('Property number or Land ID already exists.');}
  elseif($type==='ratepayers'){require_value($row,'ratepayer_number');require_value($row,'full_name');if(!in_array($row['ratepayer_type']??'',['individual','corporate'],true))throw new \DomainException('Use individual or corporate.');if($row['ratepayer_type']==='corporate')require_value($row,'organization_name');if(!empty($row['email'])&&!filter_var($row['email'],FILTER_VALIDATE_EMAIL))throw new \DomainException('Invalid email.');if(Database::one('SELECT id FROM ratepayers WHERE ratepayer_number=?',[$row['ratepayer_number']]))throw new \DomainException('Ratepayer already exists.');}
  elseif($type==='accounts'){$property=Database::one('SELECT id FROM properties WHERE property_number=?',[require_value($row,'account_number')])??throw new \DomainException('Property not found.');$row['account_number']=$property['id'];require_value($row,'account_number');valid_date(require_value($row,'opened_on'));if(Database::one("SELECT id FROM accounts WHERE account_number=? OR (account_number=? AND status='active')",[$row['account_number'],$property['id']]))throw new \DomainException('Account exists or property already has an active account.');}
  elseif($type==='opening_balances'){$account=Database::one('SELECT id FROM accounts WHERE account_number=?',[require_value($row,'account_number')])??throw new \DomainException('Account not found.');$row['account_number']=$account['id'];$year=(int)require_value($row,'billing_year');if($year<1900||$year>2200)throw new \DomainException('Invalid billing year.');if(Money::cmp(Money::parse(require_value($row,'amount')),'0')<=0)throw new \DomainException('Amount must be positive.');valid_date(require_value($row,'due_date'));require_value($row,'reference');if(Database::one('SELECT id FROM ground_rent_bills WHERE account_number=? AND billing_year=?',[$account['id'],$year]))throw new \DomainException('Account already has a bill for this year.');}
  else throw new \DomainException('Invalid import type.');return $row;
 }
 public static function upload(array $file,string $type): string {Auth::staff();if(!isset(self::TEMPLATES[$type]))throw new \DomainException('Invalid import type.');if(($file['error']??4)!==0||!is_uploaded_file($file['tmp_name'])||filesize($file['tmp_name'])>10*1024*1024)throw new \DomainException('Choose a CSV or Excel file up to 10 MB.');$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!in_array($ext,['csv','xlsx'],true))throw new \DomainException('Use CSV or XLSX.');if($ext==='xlsx'){$zip=new \ZipArchive();if($zip->open($file['tmp_name'])!==true)throw new \DomainException('Invalid XLSX archive.');$expanded=0;for($i=0;$i<$zip->numFiles;$i++){$entry=$zip->statIndex($i);$expanded+=$entry['size'];if($expanded>50*1024*1024){$zip->close();throw new \DomainException('Expanded spreadsheet exceeds 50 MB.');}}$zip->close();}$reader=$ext==='csv'?new \PhpOffice\PhpSpreadsheet\Reader\Csv():new \PhpOffice\PhpSpreadsheet\Reader\Xlsx();$reader->setReadDataOnly(true);$book=$reader->load($file['tmp_name']);$sheet=$book->getActiveSheet();if($sheet->getHighestDataRow()>(int)Settings::get('import_max_rows','5000')+1)throw new \DomainException('Import exceeds the configured row limit.');$rows=$sheet->toArray(null,false,false,false);$headers=array_map(fn($v)=>trim((string)$v),array_shift($rows)??[]);if($headers!==self::TEMPLATES[$type])throw new \DomainException('Headers must match the downloadable template exactly.');return Database::transaction(function()use($file,$type,$rows,$headers){$batch=Database::insert('import_batches',['source_filename'=>basename($file['name']),'entity_type'=>$type,'status'=>'validated','created_by'=>Auth::user()['id'],'file_hash'=>hash_file('sha256',$file['tmp_name'])]);$seen=[];$good=0;$bad=0;$number=1;foreach($rows as $cells){$number++;if(!array_filter($cells,fn($v)=>$v!==null&&$v!==''))continue;$row=array_combine($headers,array_slice(array_pad($cells,count($headers),null),0,count($headers)));$error=null;try{$row=self::normalize($type,$row);$key=$type==='opening_balances'?$row['account_number'].'/'.$row['billing_year']:(string)$row[$headers[0]];$keys=[$key];if($type==='parcels'&&!empty($row['land_id']))$keys[]='land:'.$row['land_id'];if($type==='accounts'){$keys[]='property:'.$row['account_number'];if(!empty($row['land_account_number']))$keys[]='land-account:'.$row['land_account_number'];}foreach($keys as $duplicateKey){if(isset($seen[$duplicateKey]))throw new \DomainException('Duplicate identifier or relationship in this file.');}foreach($keys as $duplicateKey)$seen[$duplicateKey]=true;$good++;}catch(\Throwable $e){$error=$e->getMessage();$bad++;}Database::insert('import_rows',['batch_id'=>$batch,'row_number'=>$number,'row_data_json'=>json_encode($row,JSON_THROW_ON_ERROR),'status'=>$error?'invalid':'valid','validation_errors'=>$error]);}Database::update('import_batches',$batch,['total_rows'=>$good+$bad,'valid_rows'=>$good,'invalid_rows'=>$bad]);Audit::log('import_validated','import_batches',$batch,null,['valid'=>$good,'invalid'=>$bad]);return $batch;});}
 public static function commit(string $id): int {Auth::admin();if(Database::scalar('SELECT entity_type FROM import_batches WHERE id=?',[$id])==='billing_roll')return BillingRoll::commit($id);return Database::transaction(function()use($id){$batch=Database::lock('import_batches',$id);if($batch['invalid_rows']>0)throw new \DomainException('Correct invalid rows and upload a new file before approval.');if(!in_array($batch['status'],['validated','processing','failed'],true))throw new \DomainException('Batch cannot be committed.');Database::update('import_batches',$id,['status'=>'processing','approved_by'=>$batch['approved_by']??Auth::user()['id'],'approved_at'=>$batch['approved_at']??date('Y-m-d H:i:s'),'started_at'=>$batch['started_at']??date('Y-m-d H:i:s')]);if(in_array($batch['entity_type'],['parcels','ratepayers'],true)){$migrated=(int)Database::scalar("SELECT COUNT(*) FROM import_rows r JOIN import_batches b ON b.id=r.batch_id WHERE r.status='imported' AND b.entity_type IN ('parcels','ratepayers')");$pending=(int)Database::scalar("SELECT COUNT(*) FROM import_rows WHERE batch_id=? AND status<>'imported'",[$id]);if($migrated+$pending>10000)throw new \DomainException('The 10,000 property/ratepayer migration limit would be exceeded.');}$rows=Database::all(Database::page("SELECT * FROM import_rows WHERE batch_id=? AND status IN ('valid','failed') ORDER BY row_number",1,(int)Settings::get('import_chunk_rows','100')),[$id]);foreach($rows as $r){$d=self::normalize($batch['entity_type'],json_decode($r['row_data_json'],true));$target=$batch['entity_type']==='opening_balances'?Finance::opening($d):Registry::save($batch['entity_type'],$d);Database::update('import_rows',$r['id'],['status'=>'imported','target_entity_id'=>$target,'processed_at'=>date('Y-m-d H:i:s'),'validation_errors'=>null]);}$remaining=(int)Database::scalar("SELECT COUNT(*) FROM import_rows WHERE batch_id=? AND status<>'imported'",[$id]);if(!$remaining)Database::update('import_batches',$id,['status'=>'completed','completed_at'=>date('Y-m-d H:i:s')]);Audit::log('import_chunk_committed','import_batches',$id,null,['rows'=>count($rows),'remaining'=>$remaining]);return $remaining;});}
}
